static inline void put(const uint8_t *p, size_t n) {
    for (size_t i = 0; i < n; i++) {
        if (p[i] == '\t') fputs("\\t", stdout);
        else if (p[i] == '\n') fputs("\\n", stdout);
        else if (p[i] == '\\') fputs("\\\\", stdout);
        else putchar(p[i]);
    }
}

/* S unescaped in place; its length. */
static inline size_t unescape(char *s) {
    size_t o = 0;
    for (size_t i = 0; s[i]; i++) {
        if (s[i] == '\\' && s[i + 1] == 't') { s[o++] = '\t'; i++; }
        else if (s[i] == '\\' && s[i + 1] == 'n') { s[o++] = '\n'; i++; }
        else if (s[i] == '\\' && s[i + 1] == '\\') { s[o++] = '\\'; i++; }
        else s[o++] = s[i];
    }
    s[o] = 0;
    return o;
}

static inline int arg_int(const char *s, int64_t *v) {
    char *end;
    errno = 0;
    long long x = strtoll(s, &end, 10);
    if (!*s || *end || errno) return 0;
    *v = (int64_t)x;
    return 1;
}

static inline int arg_bool(const char *s, bool *v) {
    if (!strcmp(s, "true")) { *v = true; return 1; }
    if (!strcmp(s, "false")) { *v = false; return 1; }
    return 0;
}

static inline int arg_float64(const char *s, double *v) {
    char *end;
    *v = strtod(s, &end);
    return *s && !*end;
}

/* A str argument: its bytes, or the previous str result for "@". */
static inline void arg_str(char *s, size_t len, const uint8_t **p, size_t *n) {
    if (len == 1 && s[0] == '@' && last) { *p = last; *n = last_len; return; }
    *p = (const uint8_t *)s;
    *n = len;
}

static inline void keep(const uint8_t *p, size_t n) {
    free(last);
    last = malloc(n + 1);
    if (!last) { fputs("out of memory\n", stderr); exit(70); }
    memcpy(last, p, n);
    last_len = n;
}

static const char *status_name(int32_t status) {
    switch (status) {
    case game_STATUS_OK: return "ok";
    case game_STATUS_DECLARED: return "declared";
    case game_STATUS_RUNTIME: return "runtime";
    case game_STATUS_BOUNDARY: return "boundary";
    case game_STATUS_INVOCATION: return "invocation";
    case game_STATUS_INTERNAL: return "internal";
    default: return "unknown";
    }
}

/* Writes the failed call NAME's outcome, and releases its error E (the
 * caller owns it: RELEASE, the manifest's release function). */
static void report(const char *name, int32_t status, game_error *e, int32_t (*release)(game_error **)) {
    printf("%s\terror\t%s", name, status_name(status));
    if (e) {
        const uint8_t *p;
        size_t n;
        if (game_error_identity(e, &p, &n) == game_STATUS_OK) { putchar('\t'); put(p, n); }
        size_t count = game_error_field_count(e);
        for (size_t i = 0; i < count; i++) {
            putchar('\t');
            if (game_error_field_name(e, i, &p, &n) == game_STATUS_OK) put(p, n);
            putchar('=');
            switch (game_error_field_type(e, i)) {
            case game_FIELD_INT: { int64_t v; if (game_error_field_int(e, i, &v) == game_STATUS_OK) printf("%lld", (long long)v); else fputs("(beyond int64_t)", stdout); break; }
            case game_FIELD_BOOL: { bool v = false; game_error_field_bool(e, i, &v); fputs(v ? "true" : "false", stdout); break; }
            case game_FIELD_FLOAT64: { double v = 0; game_error_field_float64(e, i, &v); printf("%.17g", v); break; }
            case game_FIELD_STR: { if (game_error_field_str(e, i, &p, &n) == game_STATUS_OK) put(p, n); break; }
            default: fputs("(other)", stdout);
            }
        }
        release(&e);
    }
    putchar('\n');
}

